or 2x2\n  task automatic compute_2x2_block;\n    input  int base_row;\n    input  int base_col;\n    input  [63:0] timg;\n    output [3:0] best_img;\n    output [3:0] best_cost;\n    integer r,c;\n    integer idx_flat;\n    reg [3:0] tgt4;\n    integer ones_cnt;\n    integer zeros_cnt;\n    reg [3:0] white_cost;\n    reg [3:0] black_cost;\n    begin\n      // Collect 4 target bits (row-wise, MSB-first inside block)\n      tgt4 = 4'b0;\n      for (r = 0; r < 2; r = r+1) begin\n        for (c = 0; c < 2; c = c+1) begin\n          idx_flat = (base_row + r)*8 + (base_col + c);\n          tgt4[3 - (r*2 + c)] = tgt_bit(timg, idx_flat);\n        end\n      end\n\n      ones_cnt  = tgt4[3] + tgt4[2] + tgt4[1] + tgt4[0];\n      zeros_cnt = 4 - ones_cnt;\n\n      white_cost = zeros_cnt[3:0]; // all 1's vs tgt\n      black_cost = ones_cnt[3:0]; // all 0's vs tgt\n\n      if (white_cost <= black_cost) begin\n        best_cost = white_cost;\n        best_img  = 4'b1111;\n      end else begin\n        best_cost = black_cost;\n        best_img  = 4'b0000;\n      end\n    end\n  endtask\n\n  // Combinational helper for 4x4 from four 2x2\n  task automatic compute_4x4_block;\n    input  [3:0]  q_cost0;\n    input  [3:0]  q_cost1;\n    input  [3:0]  q_cost2;\n    input  [3:0]  q_cost3;\n    input  [3:0]  q_img0;\n    input  [3:0]  q_img1;\n    input  [3:0]  q_img2;\n    input  [3:0]  q_img3;\n    input  [63:0] timg;\n    input  int base_row;\n    input  int base_col;\n    output [15:0] best_img;\n    output [4:0]  best_cost;\n\n    integer r,c;\n    integer idx_flat;\n    integer i;\n    reg [15:0] tgt16;\n    integer ones_cnt;\n    integer zeros_cnt;\n    reg [4:0] white_cost;\n    reg [4:0] black_cost;\n    reg [4:0] quad_cost;\n    reg [15:0] quad_img;\n    begin\n      // Build tgt16\n      tgt16 = 16'b0;\n      for (r = 0; r < 4; r = r+1) begin\n        for (c = 0; c < 4; c = c+1) begin\n          idx_flat = (base_row + r)*8 + (base_col + c);\n          tgt16[15 - (r*4 + c)] = tg